import React, { useState } from 'react';
import axios from 'axios';

const JobForm = ({ fetchJobs }) => {
    const [formData, setFormData] = useState({
        company: '',
        role: '',
        status: 'Applied',
        dateOfApplication: '',
        link: ''
    });

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        await axios.post('/api/jobs', formData);
        fetchJobs();
        setFormData({ company: '', role: '', status: 'Applied', dateOfApplication: '', link: '' });
    };

    return (
        <form onSubmit={handleSubmit}>
            <input type="text" name="company" value={formData.company} onChange={handleChange} placeholder="Company" required />
            <input type="text" name="role" value={formData.role} onChange={handleChange} placeholder="Role" required />
            <select name="status" value={formData.status} onChange={handleChange}>
                <option value="Applied">Applied</option>
                <option value="Interview">Interview</option>
                <option value="Offer">Offer</option>
                <option value="Rejected">Rejected</option>
            </select>
            <input type="date" name="dateOfApplication" value={formData.dateOfApplication} onChange={handleChange} required />
            <input type="url" name="link" value={formData.link} onChange={handleChange} placeholder="Link" required />
            <button type="submit">Add Job</button>
        </form>
    );
};

export default JobForm;
